(1, 'Musyawarah Penetapan Utusan Peserta Musyawarah Pemilihan Anggota BPD Desa Rawapanjang Masa Bakti 2027-2035', 'musyawarah-penetapan-utusan-peserta-musyawarah-pemilihan-anggota-bpd-desa-rawapanjang-masa-bakti-2027-2035', 'berita', NULL, '<p>Ketua RW 09 H. Slamet Santoso terlihat memimpin acara Musyawarah Penetapan Utusan Peserta Musyawarah Pemilihan Anggota BPD Desa Rawapanjang Masa Bakti 2027-2035 yang di hadiri oleh pengurus dibawah jajaran RW 09 yaitu RT 01, RT 02, RT 03, RT 04, RT 05, RT 06</p>', 'publish', 1, (SELECT id FROM users WHERE username = 'admin' LIMIT 1), '2026-10-18 07:28:18', '2026-10-18 12:28:18', '2026-10-18 13:14:02');
