(15, 'Kerja Bakti Serentak Sepanjang Jalan Kampung Panjang Desa Rawa Panjang', 'kerja-bakti-serentak-sepanjang-jalan-kampung-panjang-desa-rawa-panjang-2', 'kegiatan', 1, '<p>Telah dilakukan Kegiatan Warga RT 03 RW 09:</p><ol><li>Kegiatan pembersihan saluran got wilayah RT 03</li><li>Pengangkatan batu yang menutup got</li><li>Merapihkan pinggiran jalan</li></ol>', 'publish', 0, (SELECT id FROM users WHERE username = 'admin' LIMIT 1), '2026-10-18 08:47:03', '2026-10-18 13:47:03', '2026-10-18 14:15:50');
